import{_ as h,C as e,o as c,c as u,j as n,a,E as o}from"./chunks/framework.Bf1r8NYr.js";const x=JSON.parse('{"title":"Quiz — Bài 1","description":"","frontmatter":{"quizKey":"module-1-dmp","questions":[{"id":"1.1.","text":"DMP khác protocol ở điểm nào?","options":[{"key":"A","text":"Protocol nói nghiên cứu làm gì; DMP nói dữ liệu được quản trị ra sao trong nghiên cứu."},{"key":"B","text":"Protocol và DMP mô tả nội dung tương tự, nhưng khác cách trình bày trong quản trị dữ liệu."},{"key":"C","text":"DMP mô tả kế hoạch phân tích, còn protocol mô tả cách lưu trữ dữ liệu ở từng giai đoạn."},{"key":"D","text":"DMP phù hợp khi nghiên cứu có dữ liệu mở hoặc dùng công cụ AI trong một số trường hợp."}],"answer":"A","explain":"Protocol tập trung vào câu hỏi và quy trình nghiên cứu; DMP tập trung vào dữ liệu, người dùng và chia sẻ."},{"id":"1.2.","text":"Vì sao cần lập DMP/DMSP trước khi thu thập dữ liệu?","options":[{"key":"A","text":"Để có thể bỏ qua việc thống nhất biến nếu biểu mẫu đã có sẵn."},{"key":"B","text":"Để thống nhất dữ liệu cần thu, metadata, lưu trữ và chia sẻ trước khi quyết định thượng nguồn."},{"key":"C","text":"Để thay thế protocol bằng một tài liệu ngắn hơn và dễ phê duyệt hơn."},{"key":"D","text":"Để chọn kho lưu trữ trước, còn chất lượng dữ liệu tính sau khi thu thập."}],"answer":"B","explain":"Lập kế hoạch sớm giúp các quyết định về biến, metadata, lưu trữ và chia sẻ nhất quán từ đầu."},{"id":"1.3.","text":"Vì sao cần metadata?","options":[{"key":"A","text":"Để biến các trường dữ liệu thành cùng một kiểu và cùng một đơn vị khi phân tích."},{"key":"B","text":"Để thay thế trực tiếp từ điển dữ liệu và nhật ký xử lý trong nghiên cứu."},{"key":"C","text":"Để giữ lại ngữ cảnh về cách dữ liệu được thu thập, mô tả và sử dụng."},{"key":"D","text":"Để dữ liệu cần metadata khi được công bố công khai hoặc chia sẻ có kiểm soát."}],"answer":"C","explain":"Metadata giúp người khác hiểu dữ liệu và đánh giá khả năng tái sử dụng sau này."},{"id":"1.4.","text":"Tình huống: Một nghiên cứu ghi huyết áp bằng “120/80”, “120” hoặc “cao”. Cách phòng lỗi phù hợp nhất là gì?","options":[{"key":"A","text":"Chọn một cách ghi sau khi phân tích để bảng dữ liệu ngắn hơn và dễ đọc hơn."},{"key":"B","text":"Giữ nguyên các cách ghi vì chúng đều phản ánh một lần đo."},{"key":"C","text":"Chuyển các giá trị sang văn bản để giữ lại thông tin ban đầu trong bảng."},{"key":"D","text":"Thống nhất định nghĩa biến, từ điển dữ liệu và đơn vị trước khi thu thập."}],"answer":"D","explain":"Chuẩn hóa biến và đơn vị ở bước thiết kế giúp dữ liệu nhất quán ngay khi được thu thập."}]},"headers":[],"relativePath":"course/module-1-dmp/quiz.md","filePath":"course/module-1-dmp/quiz.md"}'),g={name:"course/module-1-dmp/quiz.md"};function r(l,t,d,s,p,k){const i=e("Quiz",!0);return c(),u("div",null,[t[0]||(t[0]=n("h1",{id:"quiz-—-bai-1",tabindex:"-1"},[a("Quiz — Bài 1 "),n("a",{class:"header-anchor",href:"#quiz-—-bai-1","aria-label":'Permalink to "Quiz — Bài 1"'},"​")],-1)),o(i)])}const y=h(g,[["render",r]]);export{x as __pageData,y as default};
